package constants;

/**
 * Moi hang so cua chuong trinh: so cua menu, loai tai lieu, han muon + phi tre tung loai,
 * loai nguoi muon + chinh sach phi, han muc muon,
 * luat du lieu, dinh dang bang, du lieu mau. Khong viet so hay chuoi thang trong code.
 *
 * @author CuongThai Academy
 */
public final class Constants {

    // Lua chon 0: thoat (cung la lua chon nho nhat)
    public static final int MENU_EXIT = 0;

    // Lua chon 1: them tai lieu
    public static final int MENU_ADD = 1;

    // Lua chon 2: danh sach tai lieu
    public static final int MENU_LIST = 2;

    // Lua chon 3: tim tai lieu
    public static final int MENU_SEARCH = 3;

    // Lua chon 4: cap nhat so ban
    public static final int MENU_UPDATE_COPIES = 4;

    // Lua chon 5: xoa tai lieu
    public static final int MENU_DELETE = 5;

    // Lua chon 6: them thanh vien
    public static final int MENU_ADD_MEMBER = 6;

    // Lua chon 7: danh sach thanh vien
    public static final int MENU_LIST_MEMBERS = 7;

    // Lua chon 8: thong ke
    public static final int MENU_REPORT = 8;

    // Lua chon 9: tinh phi tre han
    public static final int MENU_LATE_FEE = 9;

    // Lua chon 10: muon tai lieu
    public static final int MENU_BORROW = 10;

    // Lua chon 11: tra tai lieu (cung la lua chon lon nhat)
    public static final int MENU_RETURN = 11;

    // Loai tai lieu 1: sach (cung la loai nho nhat)
    public static final int TYPE_BOOK = 1;

    // Loai tai lieu 2: tap chi
    public static final int TYPE_MAGAZINE = 2;

    // Loai tai lieu 3: DVD (cung la loai lon nhat)
    public static final int TYPE_DVD = 3;

    // Sach: muon 14 ngay
    public static final int BOOK_LOAN_DAYS = 14;

    // Sach: tre 2000 dong moi ngay
    public static final int BOOK_LATE_FEE = 2000;

    // Tap chi: muon 7 ngay
    public static final int MAGAZINE_LOAN_DAYS = 7;

    // Tap chi: tre 1000 dong moi ngay
    public static final int MAGAZINE_LATE_FEE = 1000;

    // DVD: muon 3 ngay
    public static final int DVD_LOAN_DAYS = 3;

    // DVD: tre 5000 dong moi ngay
    public static final int DVD_LATE_FEE = 5000;

    // Loai nguoi muon 1: sinh vien (cung la loai nho nhat, o vi tri 0 cua danh sach chinh sach)
    public static final int BORROWER_STUDENT = 1;

    // Loai nguoi muon 2: can bo (cung la loai lon nhat)
    public static final int BORROWER_STAFF = 2;

    // Loai nguoi muon dau tien (de doi loai thanh vi tri trong danh sach chinh sach)
    public static final int FIRST_BORROWER_TYPE = 1;

    // Moi thanh vien muon cung luc toi da 3 tai lieu
    public static final int MAX_LOANS_PER_MEMBER = 3;

    // 100 phan tram
    public static final int PERCENT_FULL = 100;

    // Sinh vien duoc giam 50 phan tram phi tre
    public static final int STUDENT_DISCOUNT_PERCENT = 50;

    // Can bo duoc mien phi 2 ngay tre dau tien
    public static final int STAFF_FREE_DAYS = 2;

    // Tien to ma: sach
    public static final String BOOK_ID_PREFIX = "B";

    // Tien to ma: tap chi
    public static final String MAGAZINE_ID_PREFIX = "T";

    // Tien to ma: DVD
    public static final String DVD_ID_PREFIX = "D";

    // Dinh dang ma tai lieu: tien to cua loai + so thu tu 3 chu so (B001, T005, D006)
    public static final String ITEM_ID_FORMAT = "%s%03d";

    // Regex ma tai lieu: B, T hoac D + 3 chu so (da viet hoa truoc khi so)
    public static final String REGEX_ITEM_ID = "[BTD]\\d{3}";

    // Regex ma thanh vien: M + 3 chu so (da viet hoa truoc khi so)
    public static final String REGEX_MEMBER_ID = "M\\d{3}";

    // Do dai toi da cua ten
    public static final int TITLE_MAX_LENGTH = 60;

    // So chu so cua ISBN-13
    public static final int ISBN_LENGTH = 13;

    // So chu so dau (tien to) cua ISBN-13: 978 hoac 979
    public static final int ISBN_PREFIX_LENGTH = 3;

    // Tien to ISBN-13 thu nhat
    public static final String ISBN_PREFIX_978 = "978";

    // Tien to ISBN-13 thu hai
    public static final String ISBN_PREFIX_979 = "979";

    // Trong so cua chu so o vi tri le (thu 2, 4, ...): 3; vi tri chan: 1
    public static final int ISBN_ODD_WEIGHT = 3;

    // Chia lay du cho 10 khi tinh chu so kiem tra
    public static final int ISBN_MODULO = 10;

    // Cac chu so; vi tri cua 1 ky tu trong chuoi nay chinh la gia tri cua no
    public static final String DIGITS = "0123456789";

    // Hai ky tu duoc phep go xen trong ISBN (se bi bo di)
    public static final String ISBN_SEPARATORS = "- ";

    // Nam xuat ban nho nhat (sach in dau tien cua Gutenberg ~1450)
    public static final int YEAR_MIN = 1450;

    // So ban nho nhat (0 = tam het)
    public static final int COPIES_MIN = 0;

    // So ban lon nhat cua 1 tai lieu
    public static final int COPIES_MAX = 99;

    // Ky so tap chi nho nhat
    public static final int ISSUE_MIN = 1;

    // Ky so tap chi lon nhat
    public static final int ISSUE_MAX = 999;

    // Thoi luong DVD ngan nhat (phut)
    public static final int MINUTES_MIN = 1;

    // Thoi luong DVD dai nhat (phut)
    public static final int MINUTES_MAX = 600;

    // So ngay giu nho nhat khi tinh phi (tra ngay trong ngay)
    public static final int DAYS_KEPT_MIN = 0;

    // So ngay giu lon nhat khi tinh phi (1 nam)
    public static final int DAYS_KEPT_MAX = 365;

    // Regex ten nguoi: chu cai khong dau va dau cach
    public static final String REGEX_PERSON_NAME = "[A-Za-z ]+";

    // Regex email (da viet thuong): ten [a-z0-9] noi bang . _ - ; ten mien co it nhat 1 dau cham
    public static final String REGEX_EMAIL
            = "[a-z0-9]+([._-][a-z0-9]+)*@[a-z0-9]+(-[a-z0-9]+)*(\\.[a-z0-9]+(-[a-z0-9]+)*)+";

    // Regex nhieu dau cach lien nhau (de gop thanh 1)
    public static final String REGEX_SPACES = "\\s+";

    // Mot dau cach
    public static final String SPACE = " ";

    // Dinh dang ma thanh vien: M + so thu tu 3 chu so
    public static final String MEMBER_ID_FORMAT = "M%03d";

    // So thu tu dau tien khi cap ma (B001, M001)
    public static final int FIRST_ID_NUMBER = 1;

    // Dong bang tai lieu: No, ma, loai, nam, so ban, han muon, phi/ngay, ten, chi tiet
    public static final String ITEM_TABLE_FORMAT = "%-3s %-5s %-8s %-5s %-6s %-5s %-6s %-29s %s";

    // Dinh dang 1 dong bang thanh vien: No, ma, ho ten, email
    public static final String MEMBER_TABLE_FORMAT = "%-3s %-5s %-22s %s";

    // Sach mau: { ten sach, ISBN-13, tac gia, nam, so ban }
    public static final String[][] SAMPLE_BOOK_ARRAY = {
        {"The Pragmatic Programmer", "9780135957059", "David Thomas", "2019", "3"},
        {"Effective Java", "9780134685991", "Joshua Bloch", "2018", "2"},
        {"Java Concurrency In Practice", "9780321349606", "Brian Goetz", "2006", "1"},
        {"Head First Java", "9780596009205", "Kathy Sierra", "2005", "4"},
    };

    // Vi tri cot ten sach trong 1 dong sach mau
    public static final int SAMPLE_TITLE_INDEX = 0;

    // Vi tri cot ISBN trong 1 dong sach mau
    public static final int SAMPLE_ISBN_INDEX = 1;

    // Vi tri cot tac gia trong 1 dong sach mau
    public static final int SAMPLE_AUTHOR_INDEX = 2;

    // Vi tri cot nam xuat ban trong 1 dong sach mau
    public static final int SAMPLE_YEAR_INDEX = 3;

    // Vi tri cot so ban trong 1 dong sach mau
    public static final int SAMPLE_COPIES_INDEX = 4;

    // Tap chi mau: { ten, nam, so ban, ky so }
    public static final String[][] SAMPLE_MAGAZINE_ARRAY = {
        {"Tech Weekly", "2025", "2", "118"},
    };

    // DVD mau: { ten, nam, so ban, so phut }
    public static final String[][] SAMPLE_DVD_ARRAY = {
        {"The Social Network", "2010", "1", "120"},
    };

    // Vi tri cot ten trong 1 dong tap chi / DVD mau
    public static final int SAMPLE_OTHER_TITLE_INDEX = 0;

    // Vi tri cot nam trong 1 dong tap chi / DVD mau
    public static final int SAMPLE_OTHER_YEAR_INDEX = 1;

    // Vi tri cot so ban trong 1 dong tap chi / DVD mau
    public static final int SAMPLE_OTHER_COPIES_INDEX = 2;

    // Vi tri cot cuoi (ky so cua tap chi, so phut cua DVD)
    public static final int SAMPLE_EXTRA_INDEX = 3;

    // Thanh vien mau: { ho ten, email }
    public static final String[][] SAMPLE_MEMBER_ARRAY = {
        {"Tran Thi Binh", "binh.tran@ctlib.vn"},
        {"Nguyen Van An", "an.nguyen@ctlib.vn"},
    };

    // Vi tri cot ho ten trong 1 dong thanh vien mau
    public static final int SAMPLE_NAME_INDEX = 0;

    // Vi tri cot email trong 1 dong thanh vien mau
    public static final int SAMPLE_EMAIL_INDEX = 1;

    // Ngan khong cho tao doi tuong Constants
    private Constants() {
    }
}

