package dto;

import constants.Constants;

/**
 * Mot dong bang tai lieu Controller gui sang View de in.
 * BAN SAO du lieu cua mot LibraryItem (sach, tap chi hay DVD): loai, chi tiet, han muon
 * va phi/ngay da duoc chinh doi tuong do tra loi (da hinh) khi kho chep sang.
 *
 * @author CuongThai Academy
 */
public class BookResponseDTO {

    // So thu tu dong (danh sau khi sap xep)
    private int no;

    // Ma tai lieu
    private String id;

    // Ten loai (Sach, Tap chi, DVD)
    private String typeName;

    // Ten
    private String title;

    // Nam
    private int year;

    // So ban
    private int copies;

    // So ngay duoc muon
    private int loanDays;

    // Phi tre moi ngay (dong)
    private int lateFeePerDay;

    // Thong tin rieng cua loai (tac gia + ISBN, ky so, so phut)
    private String detail;

    // Constructor rong (JavaBean)
    public BookResponseDTO() {
    }

    // Constructor phan dinh danh (so thu tu, han muon, phi, chi tiet gan sau qua setter)
    public BookResponseDTO(String id, String typeName, String title, int year, int copies) {
        this.id = id;
        this.typeName = typeName;
        this.title = title;
        this.year = year;
        this.copies = copies;
    }

    // Tra ve so thu tu
    public int getNo() {
        return no;
    }

    // Gan so thu tu
    public void setNo(int no) {
        this.no = no;
    }

    // Tra ve ma
    public String getId() {
        return id;
    }

    // Gan ma
    public void setId(String id) {
