giai.main/Main.java:
package main;

import constants.Constants;
import constants.Message;
import controller.BookController;
import controller.MemberController;
import dto.BookRequestDTO;
import dto.LoanRequestDTO;
import dto.MemberRequestDTO;
import exceptions.InvalidInputException;
import java.util.Scanner;
import utils.Validation;

/**
 * Diem bat dau cua CT Library: in menu, doc va kiem moi o nhap (qua utils),
 * moi lua chon goi Controller dung 1 lan. Main khong biet sach/thanh vien nam o dau.
 * Lab 6: Main chi bat InvalidInputException (loi nhap — hoi lai); loi nghiep vu da duoc
 * Controller bat. Scanner mo bang try-with-resources nen tu dong dong khi thoat.
 *
 * @author CuongThai Academy
 */
public final class Main {

    // Ngan khong cho tao doi tuong Main (Main chi co ham static)
    private Main() {
    }

    // Mo ban phim bang try-with-resources roi chay menu; ra khoi khoi try la Scanner tu dong
    public static void main(String[] args) {
        // Scanner tu dong close() khi khoi try ket thuc, ke ca khi co ngoai le lot ra
        try (Scanner scanner = new Scanner(System.in)) {
            runMenu(scanner);
        }
    }

    // Lap menu den khi chon 0
    private static void runMenu(Scanner scanner) {
        // Cac controller, phieu muon/tra dung chung, co chay cua vong lap menu
        BookController bookController = new BookController();
        MemberController memberController = new MemberController();
        LoanRequestDTO loanRequestDTO = new LoanRequestDTO();
        boolean isRunning = true;

        // Lap lai menu sau moi chuc nang
        while (isRunning) {
            // In menu
            System.out.println(Message.MENU_HEADER);
            System.out.println(Message.MENU_BODY);

            // Chay chuc nang nguoi dung chon, moi case goi Controller 1 lan
            switch (getMenuChoice(scanner)) {
                // 1: chon loai, nhap du thong tin roi them tai lieu
                case Constants.MENU_ADD:
                    System.out.println(Message.TITLE_ADD);
                    bookController.addItem(inputItem(scanner));
                    break;

                // 2: in moi tai lieu sap theo ten
                case Constants.MENU_LIST:
                    System.out.println(Message.TITLE_LIST);
                    bookController.showAllItems();
                    break;

                // 3: nhap tu khoa roi tim tai lieu
                case Constants.MENU_SEARCH:
                    System.out.println(Message.TITLE_SEARCH);
                    bookController.searchItems(inputKeyword(scanner));
                    break;

                // 4: nhap ma + so ban moi roi cap nhat
                case Constants.MENU_UPDATE_COPIES:
                    System.out.println(Message.TITLE_UPDATE_COPIES);
                    bookController.updateCopies(inputCopiesUpdate(scanner));
                    break;

                // 5: nhap ma roi xoa
                case Constants.MENU_DELETE:
                    System.out.println(Message.TITLE_DELETE);
                    bookController.deleteItem(inputItemId(scanner));
                    break;

                // 6: nhap ho ten + email roi them thanh vien
                case Constants.MENU_ADD_MEMBER:
                    System.out.println(Message.TITLE_ADD_MEMBER);
                    memberController.addMember(inputMember(scanner));
                    break;

                // 7: in moi thanh vien sap theo ho ten
                case Constants.MENU_LIST_MEMBERS:
                    System.out.println(Message.TITLE_LIST_MEMBERS);
                    memberController.showAllMembers();
                    break;

                // 8: thong ke thu vien
                case Constants.MENU_REPORT:
                    System.out.println(Message.TITLE_REPORT);
                    bookController.showReport();
                    break;

                // 9: nhap ma, so ngay da giu, loai nguoi muon roi tinh phi tre
                case Constants.MENU_LATE_FEE:
                    System.out.println(Message.TITLE_LATE_FEE);
                    bookController.calculateLateFee(inputLateFee(scanner));
                    break;

                // 10: nhap ma thanh vien + ma tai lieu; kiem thanh vien truoc roi moi muon
                case Constants.MENU_BORROW:
                    System.out.println(Message.TITLE_BORROW);
                    loanRequestDTO = inputLoan(scanner);

                    // Thanh vien khong co thi controller da bao loi, khong goi buoc muon
                    if (memberController.checkMember(loanRequestDTO)) {
                        bookController.borrowItem(loanRequestDTO);
                    }
                    break;

                // 11: nhap ma thanh vien + ma tai lieu; kiem thanh vien truoc roi moi tra
                case Constants.MENU_RETURN:
                    System.out.println(Message.TITLE_RETURN);
                    loanRequestDTO = inputLoan(scanner);

                    // Thanh vien khong co thi controller da bao loi, khong goi buoc tra
                    if (memberController.checkMember(loanRequestDTO)) {
                        bookController.returnItem(loanRequestDTO);
                    }
                    break;

                // 0: tat co de thoat vong lap
                case Constants.MENU_EXIT:
                    System.out.println(Message.GOODBYE);
                    isRunning = false;
                    break;

                // Khong xay ra: getMenuChoice chi tra ve 0 den 11
                default:
                    break;
            }
        }
    }

    // Chon loai, nhap phan chung roi phan rieng cua loai do, gom vao 1 phieu DTO moi
    private static BookRequestDTO inputItem(Scanner scanner) {
        // Phieu moi; loai quyet dinh phai hoi them o nao
        BookRequestDTO bookRequestDTO = new BookRequestDTO();
        bookRequestDTO.setItemType(getItemType(scanner));

        // Phan chung cua moi tai lieu (moi o da kiem va chuan hoa o utils)
        bookRequestDTO.setTitle(getTitle(scanner));
        bookRequestDTO.setYear(getYear(scanner));
        bookRequestDTO.setCopies(getCopies(scanner));

        // Phan rieng: man hinh nhap la noi duy nhat (ngoai kho) can biet tung loai
        switch (bookRequestDTO.getItemType()) {
            // Sach: ISBN + tac gia
            case Constants.TYPE_BOOK:
                bookRequestDTO.setIsbn(getIsbn(scanner));
                bookRequestDTO.setAuthor(getAuthor(scanner));
                break;

            // Tap chi: ky so
            case Constants.TYPE_MAGAZINE:
                bookRequestDTO.setIssueNumber(getIssueNumber(scanner));
                break;

            // DVD: so phut
            case Constants.TYPE_DVD:
                bookRequestDTO.setMinutes(getMinutes(scanner));
                break;

            // Khong xay ra: getItemType chi tra ve 1 den 3
            default:
                break;
        }

        return bookRequestDTO;
    }

    // Nhap tu khoa tim kiem, gom vao phieu DTO (phieu chi dien ten)
    private static BookRequestDTO inputKeyword(Scanner scanner) {
        // Phieu tim kiem moi
        BookRequestDTO bookRequestDTO = new BookRequestDTO();

        // Tu khoa la 1 phan cua ten sach
        bookRequestDTO.setTitle(getKeyword(scanner));
        return bookRequestDTO;
    }

    // Nhap ma + so ban moi, gom vao phieu DTO (phieu chi dien 2 o)
    private static BookRequestDTO inputCopiesUpdate(Scanner scanner) {
        // Phieu cap nhat moi
        BookRequestDTO bookRequestDTO = new BookRequestDTO();

        // Nhap ma roi so ban moi
        bookRequestDTO.setId(getItemId(scanner));
        bookRequestDTO.setCopies(getCopies(scanner));
        return bookRequestDTO;
    }

    // Nhap ma can xoa, gom vao phieu DTO (phieu chi dien ma)
    private static BookRequestDTO inputItemId(Scanner scanner) {
        // Phieu xoa moi
        BookRequestDTO bookRequestDTO = new BookRequestDTO();

        // Nhap ma
        bookRequestDTO.setId(getItemId(scanner));
        return bookRequestDTO;
    }

    // Nhap ma, so ngay da giu, loai nguoi muon, gom vao phieu DTO (phieu chi dien 3 o)
    private static BookRequestDTO inputLateFee(Scanner scanner) {
        // Phieu tinh phi moi
        BookRequestDTO bookRequestDTO = new BookRequestDTO();

        // Nhap ma, so ngay da giu, roi loai nguoi muon
        bookRequestDTO.setId(getItemId(scanner));
        bookRequestDTO.setDaysKept(getDaysKept(scanner));
        bookRequestDTO.setBorrowerType(getBorrowerType(scanner));
        return bookRequestDTO;
    }

    // Nhap ma thanh vien + ma tai lieu, gom vao phieu muon/tra moi
    private static LoanRequestDTO inputLoan(Scanner scanner) {
        // Phieu muon/tra moi
        LoanRequestDTO loanRequestDTO = new LoanRequestDTO();

        // Nhap ma thanh vien roi ma tai lieu (da kiem dang o utils)
        loanRequestDTO.setMemberId(getMemberId(scanner));
        loanRequestDTO.setItemId(getItemId(scanner));
        return loanRequestDTO;
    }

    // Nhap ho ten + email cua 1 thanh vien, gom vao phieu DTO moi
    private static MemberRequestDTO inputMember(Scanner scanner) {
        // Phieu thanh vien moi
        MemberRequestDTO memberRequestDTO = new MemberRequestDTO();

        // Nhap ho ten roi email (da kiem o utils)
        memberRequestDTO.setName(getMemberName(scanner));
        memberRequestDTO.setEmail(getEmail(scanner));
        return memberRequestDTO;
    }

    // Hoi lua chon menu (0 den 11) den khi dung
    private static int getMenuChoice(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc ca dong roi kiem
            try {
                System.out.print(Message.INPUT_CHOICE);
                return Validation.getChoice(scanner.nextLine(), Constants.MENU_EXIT,
                        Constants.MENU_RETURN);
            } catch (InvalidInputException e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi ten den khi hop le
    private static String getTitle(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc ca dong roi kiem
            try {
                System.out.print(Message.INPUT_TITLE);
