giai.model/LibraryItem.java:
package model;

/**
 * Lop CHA TRUU TUONG (abstract) cua moi tai lieu: sach, tap chi, DVD (Lab 5).
 * Khong ai tao duoc "mot tai lieu chung chung" (new LibraryItem() la loi bien dich);
 * phan chung (ma, ten, nam, so ban) viet MOT lan o day, con 6 phuong thuc truu tuong
 * la HOP DONG: lop con nao khong cai du thi javac khong cho chay.
 *
 * @author CuongThai Academy
 */
public abstract class LibraryItem {

    // Ma tai lieu do kho cap (B001, T005, D006...)
    private String id;

    // Ten da chuan hoa (Title Case)
    private String title;

    // Nam xuat ban / phat hanh
    private int year;

    // So ban dang co tren ke
    private int copies;

    // Constructor phan chung; lop truu tuong VAN co constructor: lop con goi qua super(...)
    protected LibraryItem(String id, String title, int year, int copies) {
        this.id = id;
        this.title = title;
        this.year = year;
        this.copies = copies;
    }

    // Tra ve ma tai lieu
    public String getId() {
        return id;
    }

    // Gan ma tai lieu
    public void setId(String id) {
        this.id = id;
    }

    // Tra ve ten
    public String getTitle() {
        return title;
    }

    // Gan ten
    public void setTitle(String title) {
        this.title = title;
    }

    // Tra ve nam
    public int getYear() {
        return year;
    }

    // Gan nam
    public void setYear(int year) {
        this.year = year;
    }

    // Tra ve so ban
    public int getCopies() {
        return copies;
    }

    // Gan so ban
    public void setCopies(int copies) {
        this.copies = copies;
    }

    // Ten loai tai lieu ("Sach", "Tap chi", "DVD") — moi lop con BUOC phai tra loi
    public abstract String getTypeName();

    // Chu cai dau cua ma (B, T, D)
    public abstract String getIdPrefix();

    // So ngay duoc muon
    public abstract int getLoanDays();

    // Phi tre moi ngay (dong)
    public abstract int getLateFeePerDay();

    // Thong tin rieng cua tung loai (tac gia + ISBN, ky so, so phut)
    public abstract String getDetail();

    // Khoa chong trung (2 tai lieu cung khoa la trung)
    public abstract String getUniqueKey();
}

