import java.util.List;

/**
 * HOP DONG cua kho sach (interface): Controller chi biet "kho lam duoc gi", khong biet
 * "kho cat tai lieu o dau". Ban dau tien luu trong bo nho (InMemoryBookRepository);
 * Lab 9 them FileBookRepository (tep CSV), sau nay JdbcBookRepository (PostgreSQL) —
 * cung cai interface nay nen Main va Controller khong phai doi.
 * Ten co tien to I: checklist thay muc 1.3 (interface I..., nhu ISortStrategy trong bai mau).
 * Lab 6: moi phuong thuc khai DUNG ngoai le no nem (het 'Exception chung chung') — hop dong
 * noi ro ca nhung gi co the hong, va ban cai nao cung phai giu dung cac loi do.
 *
 * @author CuongThai Academy
 */
public interface IBookRepository {

    // Them 1 tai lieu tu phieu, tra ve ma vua cap; trung khoa thi nem loi
    String addItem(BookRequestDTO bookRequestDTO) throws DuplicateKeyException;

    // Sua so ban cua tai lieu mang ma trong phieu; khong co ma thi nem loi
    void updateCopies(BookRequestDTO bookRequestDTO) throws ItemNotFoundException;

    // Xoa tai lieu mang ma nay; khong co ma thi nem loi; ma khong bao gio cap lai
    void deleteItem(String id) throws ItemNotFoundException;

    // Lay BAN SAO 1 tai lieu theo ma; khong co ma thi nem loi
    BookResponseDTO findById(String id) throws ItemNotFoundException;

    // Dem so tai lieu dang co
    int countItems();

    // Lay ban sao moi tai lieu theo thu tu da them
    List<BookResponseDTO> findAll();

    // Tim tai lieu co ten chua tu khoa (khong phan biet hoa thuong)
    List<BookResponseDTO> findByKeyword(String keyword);
}

giai.repository/InMemoryBookRepository.java:
package repository;

import constants.Constants;
import constants.Message;
import dto.BookRequestDTO;
import dto.BookResponseDTO;
import exceptions.DuplicateKeyException;
import exceptions.ItemNotFoundException;
import java.util.ArrayList;
import java.util.List;
import model.Book;
import model.Dvd;
import model.LibraryItem;
import model.Magazine;

/**
 * Ban cai dat THU NHAT cua hop dong IBookRepository: giu tai lieu trong bo nho bang MOT
 * danh sach kieu cha ArrayList&lt;LibraryItem&gt; (sach, tap chi, DVD); cap ma va lam CRUD.
 * Tat chuong trinh la mat du lieu — Lab 9 them FileBookRepository cung cai interface nay.
 * Chi createItem biet ten cac lop con; moi cho khac goi qua bien kieu cha (da hinh).
 *
 * @author CuongThai Academy
 */
public class InMemoryBookRepository implements IBookRepository {

    // Moi tai lieu dang co (sach, tap chi, DVD chung mot danh sach kieu cha)
    private List<LibraryItem> itemList;

    // So thu tu se cap cho tai lieu ke tiep (dung chung cho moi loai, khong static)
    private int nextItemNumber;

    // Tao kho rong, so thu tu dau tien la 1
    public InMemoryBookRepository() {
        itemList = new ArrayList<>();
        nextItemNumber = Constants.FIRST_ID_NUMBER;
    }

    // Them 1 tai lieu tu phieu nhap, tra ve ma vua cap; trung khoa thi nem loi
    @Override
    public String addItem(BookRequestDTO bookRequestDTO) throws DuplicateKeyException {
        // Doi tuong dung loai (bien kieu cha giu doi tuong lop con) va tai lieu trung khoa
        LibraryItem newItem = createItem(bookRequestDTO);
        LibraryItem existingItem = findByUniqueKey(newItem.getUniqueKey());

        // Trung khoa thi bao ro tai lieu nao dang giu khoa do
        if (existingItem != null) {
            throw new DuplicateKeyException(String.format(Message.ERROR_DUPLICATE_ITEM,
                    newItem.getUniqueKey(), existingItem.getTypeName(), existingItem.getId(),
                    existingItem.getTitle()));
        }

        // Ma = tien to cua loai (da hinh) + so thu tu; roi tang so thu tu cho lan sau
        newItem.setId(String.format(Constants.ITEM_ID_FORMAT, newItem.getIdPrefix(),
                nextItemNumber));
        nextItemNumber++;
        itemList.add(newItem);
        return newItem.getId();
    }

    // Sua so ban cua tai lieu mang ma trong phieu; khong co ma thi nem loi
    @Override
    public void updateCopies(BookRequestDTO bookRequestDTO) throws ItemNotFoundException {
        // item va phan tu trong itemList cung tro toi MOT doi tuong
        LibraryItem item = findItemById(bookRequestDTO.getId());

        // Khong co ma thi bao loi
        if (item == null) {
            throw new ItemNotFoundException(String.format(Message.ERROR_ITEM_NOT_FOUND,
                    bookRequestDTO.getId()));
        }

        // setCopies cua lop cha: sach, tap chi hay DVD deu dung chung
        item.setCopies(bookRequestDTO.getCopies());
    }

    // Xoa tai lieu mang ma nay; khong co ma thi nem loi. nextItemNumber KHONG lui lai
    @Override
    public void deleteItem(String id) throws ItemNotFoundException {
        // Tai lieu mang ma nay (null neu khong co)
        LibraryItem item = findItemById(id);

        // Khong co ma thi bao loi
        if (item == null) {
            throw new ItemNotFoundException(String.format(Message.ERROR_ITEM_NOT_FOUND, id));
        }

        // Bo tham chieu khoi danh sach
        itemList.remove(item);
    }

    // Lay BAN SAO 1 tai lieu theo ma; khong co ma thi nem loi
    @Override
    public BookResponseDTO findById(String id) throws ItemNotFoundException {
        // Tai lieu mang ma nay (null neu khong co)
        LibraryItem item = findItemById(id);

        // Khong co ma thi bao loi
        if (item == null) {
            throw new ItemNotFoundException(String.format(Message.ERROR_ITEM_NOT_FOUND, id));
        }

        return toResponseDTO(item);
    }

    // Dem so tai lieu dang co
    @Override
    public int countItems() {
        return itemList.size();
    }

    // Lay ban sao moi tai lieu theo thu tu da them
    @Override
    public List<BookResponseDTO> findAll() {
        // Danh sach dong bang tra ve
        List<BookResponseDTO> responseList = new ArrayList<>();

        // Moi tai lieu (du la lop con nao) doi thanh 1 dong bang
        for (LibraryItem item : itemList) {
            responseList.add(toResponseDTO(item));
        }

        return responseList;
    }

    // Tim tai lieu co ten chua tu khoa (khong phan biet hoa thuong)
    @Override
    public List<BookResponseDTO> findByKeyword(String keyword) {
        // Danh sach tim duoc; tu khoa viet thuong de so khong phan biet hoa thuong
        List<BookResponseDTO> foundList = new ArrayList<>();
        String lowerKeyword = keyword.toLowerCase();

        // Duyet tung tai lieu de so ten
        for (LibraryItem item : itemList) {
            // Ten chua tu khoa thi giu lai
            if (item.getTitle().toLowerCase().contains(lowerKeyword)) {
                foundList.add(toResponseDTO(item));
            }
        }

        return foundList;
    }

    // NOI DUY NHAT biet ten cac lop con: tao doi tuong dung loai tu phieu (ma gan sau)
    private LibraryItem createItem(BookRequestDTO bookRequestDTO) {
        // Loai trong phieu quyet dinh lop con; bien kieu cha giu duoc ca ba (upcasting)
        switch (bookRequestDTO.getItemType()) {
            // 1: sach can them ISBN + tac gia
            case Constants.TYPE_BOOK:
                return new Book("", bookRequestDTO.getIsbn(), bookRequestDTO.getTitle(),
                        bookRequestDTO.getAuthor(), bookRequestDTO.getYear(),
                        bookRequestDTO.getCopies());
            // 2: tap chi can them ky so
            case Constants.TYPE_MAGAZINE:
                return new Magazine("", bookRequestDTO.getTitle(), bookRequestDTO.getYear(),
                        bookRequestDTO.getCopies(), bookRequestDTO.getIssueNumber());
            // 3: DVD can them so phut
            case Constants.TYPE_DVD:
                return new Dvd("", bookRequestDTO.getTitle(), bookRequestDTO.getYear(),
                        bookRequestDTO.getCopies(), bookRequestDTO.getMinutes());
            // Loai khac la BUG cua lap trinh vien (utils chi cho 1 den 3): ngoai le UNCHECKED,
            // khong bat o dau ca — de bug hien ro thay vi lang lang chay sai
            default:
                throw new IllegalArgumentException(Message.ERROR_ITEM_TYPE);
        }
    }

    // Tim tai lieu theo ma; khong co thi tra null
    private LibraryItem findItemById(String id) {
        // Duyet tung tai lieu de so ma
        for (LibraryItem item : itemList) {
            // So chuoi bang equals, khong bao gio bang ==
            if (item.getId().equals(id)) {
                return item;
            }
        }

        return null;
    }

    // Tim tai lieu cung khoa chong trung; khong co thi tra null
    private LibraryItem findByUniqueKey(String uniqueKey) {
        // getUniqueKey() chay ban cua lop con: sach so ISBN, tap chi so ten + ky...
        for (LibraryItem item : itemList) {
            // Cung khoa la trung
            if (item.getUniqueKey().equals(uniqueKey)) {
                return item;
            }
        }

        return null;
    }

    // Chep 1 tai lieu sang 1 dong bang MOI; khong hoi "ban la lop nao": doi tuong tu tra loi
    private BookResponseDTO toResponseDTO(LibraryItem item) {
        // Phan chung doc qua getter cua lop cha
        BookResponseDTO responseDTO = new BookResponseDTO(item.getId(), item.getTypeName(),
                item.getTitle(), item.getYear(), item.getCopies());

        // Phan rieng: JVM chon ban ghi de theo doi tuong that (Book, Magazine hay Dvd)
        responseDTO.setLoanDays(item.getLoanDays());
        responseDTO.setLateFeePerDay(item.getLateFeePerDay());
        responseDTO.setDetail(item.getDetail());
        return responseDTO;
    }
}

