package repository;

import constants.Message;
import dto.LoanRequestDTO;
import exceptions.LoanNotFoundException;
import java.util.ArrayList;
import java.util.List;
import model.Loan;

/**
 * Kho luot muon: GIU danh sach cac luot muon dang mo va lam CRUD (them, dem, xoa).
 * Chi tra loi "co hay khong"; luat muon (han muc, con ban) la viec cua Service.
 * Lop thuong, chua tach interface: chi co 1 cach luu (bo nho). Lab 9 luu tep thi moi
 * can ILoanRepository — interface dang gia khi co ban cai thu hai.
 *
 * @author CuongThai Academy
 */
public class LoanRepository {

    // Cac luot muon dang mo
    private List<Loan> loanList;

    // Tao kho rong
    public LoanRepository() {
        loanList = new ArrayList<>();
    }

    // Ghi 1 luot muon moi (Controller da kiem luat truoc khi goi)
    public void addLoan(LoanRequestDTO loanRequestDTO) {
        loanList.add(new Loan(loanRequestDTO.getMemberId(), loanRequestDTO.getItemId()));
    }

    // Xoa luot muon cua dung thanh vien + tai lieu trong phieu; khong co thi nem loi
    public void removeLoan(LoanRequestDTO loanRequestDTO) throws LoanNotFoundException {
        // Luot muon can xoa (null neu thanh vien khong muon tai lieu nay)
        Loan loan = findLoan(loanRequestDTO);

        // Khong muon ma doi tra: bao ro ai va tai lieu nao
        if (loan == null) {
            throw new LoanNotFoundException(String.format(Message.ERROR_LOAN_NOT_FOUND,
                    loanRequestDTO.getMemberId(), loanRequestDTO.getItemId()));
        }

        // Bo luot muon khoi danh sach
        loanList.remove(loan);
    }

    // Dem so tai lieu 1 thanh vien dang muon
    public int countLoansOfMember(String memberId) {
        // So luot muon cua thanh vien nay
        int loanCount = 0;

        // Duyet tung luot muon de so ma thanh vien
        for (Loan loan : loanList) {
            // Dung thanh vien thi dem them 1
            if (loan.getMemberId().equals(memberId)) {
                loanCount++;
            }
        }

        return loanCount;
    }

    // Tim luot muon cung thanh vien va cung tai lieu; khong co thi tra null
    private Loan findLoan(LoanRequestDTO loanRequestDTO) {
        // Duyet tung luot muon, so ca hai ma bang equals
        for (Loan loan : loanList) {
            // Trung ca thanh vien lan tai lieu la dung luot muon can tim
            if ((loan.getMemberId().equals(loanRequestDTO.getMemberId()))
                    && (loan.getItemId().equals(loanRequestDTO.getItemId()))) {
                return loan;
            }
        }

        return null;
    }
}

