package repository;

import constants.Constants;
import constants.Message;
import dto.MemberRequestDTO;
import dto.MemberResponseDTO;
import exceptions.DuplicateKeyException;
import exceptions.MemberNotFoundException;
import java.util.ArrayList;
import java.util.List;
import model.Member;

/**
 * Kho thanh vien: GIU danh sach Member, cap ma thanh vien va lam CRUD (them, tim theo ma,
 * lay het). Moi email chi thuoc ve 1 thanh vien. Lab 6: nem DuplicateKeyException (trung
 * email) va MemberNotFoundException (khong co ma). Van la lop thuong — xem LoanRepository.
 *
 * @author CuongThai Academy
 */
public class MemberRepository {

    // Danh sach thanh vien
    private List<Member> memberList;

    // So thu tu se cap cho thanh vien ke tiep (truong cua doi tuong kho, khong static)
    private int nextMemberNumber;

    // Tao kho rong, ma dau tien la M001
    public MemberRepository() {
        memberList = new ArrayList<>();
        nextMemberNumber = Constants.FIRST_ID_NUMBER;
    }

    // Them 1 thanh vien tu phieu nhap, tra ve ma vua cap; email da co thi nem loi
    public String addMember(MemberRequestDTO memberRequestDTO) throws DuplicateKeyException {
        // Nguoi dang giu email nay (null neu chua co) va ma se cap
        Member existingMember = findByEmail(memberRequestDTO.getEmail());
        String newId = "";

        // Trung email thi bao ro email dang thuoc ve ai
        if (existingMember != null) {
            throw new DuplicateKeyException(String.format(Message.ERROR_DUPLICATE_EMAIL,
                    existingMember.getEmail(), existingMember.getId(), existingMember.getName()));
        }

        // Cap ma moi, tang so thu tu cho lan sau roi them thanh vien moi
        newId = String.format(Constants.MEMBER_ID_FORMAT, nextMemberNumber);
        nextMemberNumber++;
        memberList.add(new Member(newId, memberRequestDTO.getName(), memberRequestDTO.getEmail()));
        return newId;
    }

    // Lay BAN SAO 1 thanh vien theo ma; khong co ma thi nem loi
    public MemberResponseDTO findById(String id) throws MemberNotFoundException {
        // Duyet tung thanh vien de so ma (equals, khong bao gio ==)
        for (Member member : memberList) {
            // Dung ma thi tra ban sao dang dong bang
            if (member.getId().equals(id)) {
                return new MemberResponseDTO(member.getId(), member.getName(), member.getEmail());
            }
        }

        // Het danh sach ma khong thay: bao ro ma nao khong co
        throw new MemberNotFoundException(String.format(Message.ERROR_MEMBER_NOT_FOUND, id));
    }

    // Dem so thanh vien
    public int countMembers() {
        return memberList.size();
    }

    // Lay ban sao moi thanh vien (dang dong bang) theo thu tu da them
    public List<MemberResponseDTO> findAll() {
        // Danh sach dong bang tra ve
        List<MemberResponseDTO> responseList = new ArrayList<>();

        // Moi thanh vien doi thanh 1 dong bang
        for (Member member : memberList) {
            responseList.add(new MemberResponseDTO(member.getId(), member.getName(),
                    member.getEmail()));
        }

        return responseList;
    }

    // Tim thanh vien theo email; khong co thi tra null
    private Member findByEmail(String email) {
        // Duyet tung thanh vien de so email
        for (Member member : memberList) {
            // So chuoi bang equals (email da viet thuong o utils)
            if (member.getEmail().equals(email)) {
                return member;
            }
        }

        return null;
    }
}

giai.service/BookService.java:
package service;

import constants.Constants;
import constants.Message;
import dto.BookRequestDTO;
import dto.BookResponseDTO;
import dto.LateFeeDTO;
import dto.LibraryReportDTO;
import exceptions.ItemNotAvailableException;
import exceptions.LoanLimitException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * Nghiep vu tai lieu: sap xep, danh so, thong ke va tinh phi tre han tren cac dong bang
 * Controller dua vao. Service KHONG giu repository; no chi giu cac CHINH SACH phi
 * (danh sach kieu interface IFeePolicy) — luat nghiep vu, khong phai du lieu.
 * Lab 6: luat muon (han muc, con ban) cung nam o day; trai luat thi NEM ngoai le nghiep vu,
 * Service khong bat va khong in — Controller bat, View in.
 *
 * @author CuongThai Academy
 */
public class BookService {

    // Chinh sach phi theo loai nguoi muon; vi tri 0 = loai 1 (sinh vien), 1 = loai 2 (can bo)
    private List<IFeePolicy> feePolicyList;

    // Tao service voi cac chinh sach phi; them loai nguoi muon = them 1 dong o day
    public BookService() {
        feePolicyList = new ArrayList<>();
        feePolicyList.add(new StudentFeePolicy());
        feePolicyList.add(new StaffFeePolicy());
    }

    // Sap cac dong bang theo ten (A-Z, khong phan biet hoa thuong), trung ten thi theo ma;
    // xong danh so thu tu tu 1
    public List<BookResponseDTO> sortByTitle(List<BookResponseDTO> itemList) {
        // Ban sao de khong lam doi thu tu cua danh sach goc
        List<BookResponseDTO> sortedList = new ArrayList<>(itemList);

        // Comparator viet bang LOP AN DANH (Chuong 5): lop khong ten cai interface tai cho
        Collections.sort(sortedList, new Comparator<BookResponseDTO>() {
            // So ten truoc, trung ten thi so ma
            @Override
            public int compare(BookResponseDTO first, BookResponseDTO second) {
                // Ket qua so ten (0 = trung ten)
                int byTitle = first.getTitle().compareToIgnoreCase(second.getTitle());

                // Trung ten (vd 2 ky cua cung tap chi) thi ma quyet dinh thu tu
                if (byTitle == 0) {
                    return first.getId().compareTo(second.getId());
                }
                return byTitle;
            }
        });

        // Danh so thu tu sau khi sap xep
        for (int i = 0; i < sortedList.size(); i++) {
            sortedList.get(i).setNo(i + 1);
        }

        return sortedList;
    }

    // Thong ke tu danh sach Controller dua vao: so tai lieu, tong so ban, so tai lieu het,
    // tai lieu cu nhat (trung nam thi giu tai lieu gap truoc)
    public LibraryReportDTO buildReport(List<BookResponseDTO> itemList) {
        // Bao cao rong: moi so bang 0, chua co tai lieu cu nhat
        LibraryReportDTO report = new LibraryReportDTO();

        // Cong don tung tai lieu vao bao cao
        for (BookResponseDTO item : itemList) {
            report.setTotalCopies(report.getTotalCopies() + item.getCopies());

            // Het ban thi dem them 1
            if (item.getCopies() == 0) {
                report.setOutOfStockTitles(report.getOutOfStockTitles() + 1);
            }

            // Tai lieu dau tien hoac cu hon tai lieu cu nhat dang giu thi thay
            if ((report.getOldestTitle().isEmpty()) || (item.getYear() < report.getOldestYear())) {
                report.setOldestTitle(item.getTitle());
                report.setOldestYear(item.getYear());
            }
        }

        // So tai lieu la so dong cua danh sach
        report.setTotalTitles(itemList.size());
        return report;
    }

    // Tinh phi tre: ngay tre = ngay giu - han muon (khong am); phi day du = ngay tre x phi/ngay;
    // phi phai tra do CHINH SACH cua loai nguoi muon trong phieu quyet dinh (da hinh qua interface)
    public LateFeeDTO calculateLateFee(BookResponseDTO item, BookRequestDTO bookRequestDTO) {
        // Ket qua; so ngay tre; chinh sach ung voi loai nguoi muon (loai 1 o vi tri 0)
        LateFeeDTO lateFee = new LateFeeDTO();
        int daysLate = Math.max(0, bookRequestDTO.getDaysKept() - item.getLoanDays());
        IFeePolicy feePolicy = feePolicyList.get(bookRequestDTO.getBorrowerType()
                - Constants.FIRST_BORROWER_TYPE);

        // Chep thong tin tai lieu de View in
        lateFee.setId(item.getId());
        lateFee.setTitle(item.getTitle());
        lateFee.setTypeName(item.getTypeName());
        lateFee.setLoanDays(item.getLoanDays());
        lateFee.setLateFeePerDay(item.getLateFeePerDay());

        // So ngay giu, so ngay tre, phi day du, roi phi sau chinh sach
        lateFee.setDaysKept(bookRequestDTO.getDaysKept());
        lateFee.setDaysLate(daysLate);
        lateFee.setFullFee(daysLate * item.getLateFeePerDay());
        lateFee.setPolicyName(feePolicy.getPolicyName());
        lateFee.setTotalFee(feePolicy.calculateFee(daysLate, item.getLateFeePerDay()));
        return lateFee;
    }

    // Luat 1 khi muon: thanh vien chua cham han muc MAX_LOANS_PER_MEMBER; cham roi thi nem loi
    public void checkLoanLimit(String memberId, int loanCount) throws LoanLimitException {
        // Da muon du so toi da: noi ro dang muon bao nhieu tren toi da bao nhieu
        if (loanCount >= Constants.MAX_LOANS_PER_MEMBER) {
            throw new LoanLimitException(String.format(Message.ERROR_LOAN_LIMIT, memberId,
                    loanCount, Constants.MAX_LOANS_PER_MEMBER));
        }
    }

    // Luat 2 khi muon: tai lieu con it nhat 1 ban tren ke; het ban thi nem loi
    public void checkAvailable(BookResponseDTO item) throws ItemNotAvailableException {
        // Con 0 ban: noi ro tai lieu nao het
        if (item.getCopies() <= Constants.COPIES_MIN) {
            throw new ItemNotAvailableException(String.format(Message.ERROR_ITEM_NOT_AVAILABLE,
                    item.getId(), item.getTitle()));
        }
    }
}

