/**
 * Chinh sach phi tre cho can bo: mien phi 2 ngay tre dau tien, tu ngay thu 3 tinh du.
 *
 * @author CuongThai Academy
 */
public class StaffFeePolicy implements IFeePolicy {

    // Chinh sach khong giu du lieu nao
    public StaffFeePolicy() {
    }

    // Ten chinh sach, kem so ngay duoc mien lay tu Constants
    @Override
    public String getPolicyName() {
        return String.format(Message.POLICY_STAFF, Constants.STAFF_FREE_DAYS);
    }

    // Bo di STAFF_FREE_DAYS ngay tre dau (khong am), phan con lai tinh du phi
    @Override
    public int calculateFee(int daysLate, int lateFeePerDay) {
        // So ngay tre con phai tra tien
        int chargedDays = Math.max(0, daysLate - Constants.STAFF_FREE_DAYS);

        return chargedDays * lateFeePerDay;
    }
}

