package service;

import constants.Constants;
import constants.Message;

/**
 * Chinh sach phi tre cho sinh vien: tinh du ngay tre, roi giam 50%.
 *
 * @author CuongThai Academy
 */
public class StudentFeePolicy implements IFeePolicy {

    // Chinh sach khong giu du lieu nao
    public StudentFeePolicy() {
    }

    // Ten chinh sach, kem phan tram giam lay tu Constants
    @Override
    public String getPolicyName() {
        return String.format(Message.POLICY_STUDENT, Constants.STUDENT_DISCOUNT_PERCENT);
    }

    // Phi day du (ngay tre x phi/ngay) nhan phan tram con phai tra (100 - 50)
    @Override
    public int calculateFee(int daysLate, int lateFeePerDay) {
        // Phi khi chua giam
        int fullFee = daysLate * lateFeePerDay;

        return fullFee * (Constants.PERCENT_FULL - Constants.STUDENT_DISCOUNT_PERCENT)
                / Constants.PERCENT_FULL;
    }
}

giai.utils/Validation.java:
package utils;

import constants.Constants;
import constants.Message;
import exceptions.InvalidInputException;
import java.util.Calendar;

/**
 * Kiem va lam sach chu nguoi dung go: nhan chuoi Main doc duoc, tra ve gia tri sach
 * hoac nem InvalidInputException kem cau bao loi noi ro sai o dau. Khong doc ban phim.
 * Lab 6: mot lop ngoai le RIENG cho loi nhap (truoc la Exception chung chung), giu ca
 * nguyen nhan goc (NumberFormatException) qua tham so cause.
 *
 * @author CuongThai Academy
 */
public final class Validation {

    // Ngan khong cho tao doi tuong Validation (chi co ham static)
    private Validation() {
    }

    // Doi chu thanh so nguyen va kiem so nam trong [min, max]
    public static int getChoice(String input, int min, int max) throws InvalidInputException {
        // Lua chon sau khi doi
        int choice = 0;

        // Thu doi chu sang so nguyen (bo dau cach 2 dau truoc)
        try {
            choice = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu, so thuc hoac de trong: doi sang loi nhap, giu e lam nguyen nhan goc
            throw new InvalidInputException(Message.ERROR_NOT_INTEGER, e);
        }

        // Ngoai khoang thi bao khoang dung
        if ((choice < min) || (choice > max)) {
            throw new InvalidInputException(String.format(Message.ERROR_CHOICE_RANGE, min, max));
        }

        return choice;
    }

    // Chuan hoa ten tai lieu: bo dau cach thua, moi tu viet hoa chu dau (Title Case)
    public static String getTitle(String input) throws InvalidInputException {
        // Ten da chuan hoa
        String title = toTitleCase(input);

        // Rong (hoac chi co dau cach) thi bao loi
        if (title.isEmpty()) {
            throw new InvalidInputException(Message.ERROR_TITLE_EMPTY);
        }

        // Ten da chuan hoa dai qua gioi han thi bao do dai
        if (title.length() > Constants.TITLE_MAX_LENGTH) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_TITLE_LENGTH, title.length(),
                    Constants.TITLE_MAX_LENGTH));
        }

        return title;
    }

    // Kiem va chuan hoa ten tac gia
    public static String getAuthor(String input) throws InvalidInputException {
        return getPersonName(input, Message.FIELD_AUTHOR);
    }

    // Kiem va chuan hoa ho ten thanh vien
    public static String getMemberName(String input) throws InvalidInputException {
        return getPersonName(input, Message.FIELD_MEMBER_NAME);
    }

    // Doi chu thanh nam xuat ban: tu YEAR_MIN, khong lon hon nam hien tai cua may
    public static int getYear(String input) throws InvalidInputException {
        // Nam sau khi doi va nam hien tai (lay luc chay, khong viet cung)
        int year = parseInteger(input, Message.FIELD_YEAR);
        int currentYear = Calendar.getInstance().get(Calendar.YEAR);

        // O tuong lai thi bao rieng (khong in nam hien tai de output on dinh)
        if (year > currentYear) {
            throw new InvalidInputException(String.format(Message.ERROR_YEAR_FUTURE, year));
        }

        // Truoc YEAR_MIN thi bao nam nho nhat va so da nhap
        if (year < Constants.YEAR_MIN) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_YEAR_MIN, Constants.YEAR_MIN, year));
        }

        return year;
    }

    // Doi chu thanh so ban va kiem trong [COPIES_MIN, COPIES_MAX]
    public static int getCopies(String input) throws InvalidInputException {
        // So ban sau khi doi
        int copies = parseInteger(input, Message.FIELD_COPIES);

        // Ngoai khoang thi bao khoang dung va so da nhap
        if ((copies < Constants.COPIES_MIN) || (copies > Constants.COPIES_MAX)) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_NUMBER_RANGE, Message.FIELD_COPIES,
                    Constants.COPIES_MIN, Constants.COPIES_MAX, copies));
        }

        return copies;
    }

    // Kiem ma tai lieu: B, T hoac D + 3 chu so, nhan ca chu thuong (d006 -> D006)
    public static String getItemId(String input) throws InvalidInputException {
        // Ma da bo dau cach 2 dau va viet hoa
        String itemId = input.trim().toUpperCase();

        // Sai dang thi bao lai dung chu nguoi dung go
        if (!itemId.matches(Constants.REGEX_ITEM_ID)) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_ITEM_ID_FORMAT, input.trim()));
        }

        return itemId;
    }

    // Kiem ma thanh vien: M + 3 chu so, nhan ca chu thuong (m002 -> M002)
    public static String getMemberId(String input) throws InvalidInputException {
        // Ma da bo dau cach 2 dau va viet hoa
        String memberId = input.trim().toUpperCase();

        // Sai dang thi bao lai dung chu nguoi dung go
        if (!memberId.matches(Constants.REGEX_MEMBER_ID)) {
            throw new InvalidInputException(String.format(Message.ERROR_MEMBER_ID_FORMAT,
                    input.trim()));
        }

        return memberId;
    }

    // Doi chu thanh loai tai lieu: 1 sach, 2 tap chi, 3 DVD
    public static int getItemType(String input) throws InvalidInputException {
        return getChoice(input, Constants.TYPE_BOOK, Constants.TYPE_DVD);
    }

    // Doi chu thanh loai nguoi muon: 1 sinh vien, 2 can bo
    public static int getBorrowerType(String input) throws InvalidInputException {
        return getChoice(input, Constants.BORROWER_STUDENT, Constants.BORROWER_STAFF);
    }

    // Doi chu thanh ky so tap chi va kiem trong [ISSUE_MIN, ISSUE_MAX]
    public static int getIssueNumber(String input) throws InvalidInputException {
        // Ky so sau khi doi
        int issueNumber = parseInteger(input, Message.FIELD_ISSUE);

        // Ngoai khoang thi bao khoang dung va so da nhap
        if ((issueNumber < Constants.ISSUE_MIN) || (issueNumber > Constants.ISSUE_MAX)) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_NUMBER_RANGE, Message.FIELD_ISSUE,
                    Constants.ISSUE_MIN, Constants.ISSUE_MAX, issueNumber));
        }

        return issueNumber;
    }

    // Doi chu thanh so phut DVD va kiem trong [MINUTES_MIN, MINUTES_MAX]
    public static int getMinutes(String input) throws InvalidInputException {
        // So phut sau khi doi
        int minutes = parseInteger(input, Message.FIELD_MINUTES);

        // Ngoai khoang thi bao khoang dung va so da nhap
        if ((minutes < Constants.MINUTES_MIN) || (minutes > Constants.MINUTES_MAX)) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_NUMBER_RANGE, Message.FIELD_MINUTES,
                    Constants.MINUTES_MIN, Constants.MINUTES_MAX, minutes));
        }

        return minutes;
    }

    // Doi chu thanh so ngay da giu va kiem trong [DAYS_KEPT_MIN, DAYS_KEPT_MAX]
    public static int getDaysKept(String input) throws InvalidInputException {
        // So ngay sau khi doi
        int daysKept = parseInteger(input, Message.FIELD_DAYS_KEPT);

        // Ngoai khoang thi bao khoang dung va so da nhap
        if ((daysKept < Constants.DAYS_KEPT_MIN) || (daysKept > Constants.DAYS_KEPT_MAX)) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_NUMBER_RANGE, Message.FIELD_DAYS_KEPT,
                    Constants.DAYS_KEPT_MIN, Constants.DAYS_KEPT_MAX, daysKept));
        }

        return daysKept;
    }

    // Kiem email co ban: co phan truoc @, co ten mien co dau cham sau @
    public static String getEmail(String input) throws InvalidInputException {
        // Email bo dau cach 2 dau, viet thuong
        String email = input.trim().toLowerCase();

        // Sai dang thi bao lai dung chu nguoi dung go
        if (!email.matches(Constants.REGEX_EMAIL)) {
            throw new InvalidInputException(String.format(Message.ERROR_EMAIL, input.trim()));
        }

        return email;
    }

    // Kiem ISBN-13: bo dau - va dau cach, du 13 chu so, dau 978/979, dung chu so kiem tra
    public static String getIsbn(String input) throws InvalidInputException {
        // Ban go, cac chu so gom duoc, tien to, tong co trong so, chu so kiem tra, chu so cuoi
        String text = input.trim();
        StringBuilder digitBuilder = new StringBuilder();
        String prefix = "";
        int weightedSum = 0;
        int checkDigit = 0;
        int lastDigit = 0;

        // Duyet tung ky tu: chu so thi giu, dau - / dau cach thi bo, con lai la loi
        for (int i = 0; i < text.length(); i++) {
            // Ky tu dang xet
            char character = text.charAt(i);

            // Chu so thi giu lai
            if (Constants.DIGITS.indexOf(character) >= 0) {
                digitBuilder.append(character);
            } else if (Constants.ISBN_SEPARATORS.indexOf(character) < 0) {
                // Khong phai chu so cung khong phai dau ngan cach: chi ro ky tu va vi tri
                throw new InvalidInputException(
                        String.format(Message.ERROR_ISBN_CHARACTER, character, i + 1));
            }
        }

        // Thieu hoac thua chu so thi bao so chu so dang co
        if (digitBuilder.length() != Constants.ISBN_LENGTH) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_ISBN_LENGTH, Constants.ISBN_LENGTH,
                    digitBuilder.length()));
        }

        // Lay 3 chu so dau
        prefix = digitBuilder.substring(0, Constants.ISBN_PREFIX_LENGTH);

        // Ba chu so dau phai la 978 hoac 979
        if ((!prefix.equals(Constants.ISBN_PREFIX_978)) &&
                (!prefix.equals(Constants.ISBN_PREFIX_979))) {
            throw new InvalidInputException(String.format(Message.ERROR_ISBN_PREFIX, prefix));
        }

        // Cong 12 chu so dau: vi tri chan nhan 1, vi tri le nhan 3
        for (int i = 0; i < (Constants.ISBN_LENGTH - 1); i++) {
            // Gia tri cua chu so thu i
            int digit = Constants.DIGITS.indexOf(digitBuilder.charAt(i));

            // Vi tri le (1, 3, 5...) nhan 3, vi tri chan nhan 1
            if ((i % 2) == 1) {
                weightedSum = weightedSum + (digit * Constants.ISBN_ODD_WEIGHT);
            } else {
                // Vi tri chan giu nguyen
                weightedSum = weightedSum + digit;
            }
        }

        // Chu so kiem tra = (10 - tong % 10) % 10
        checkDigit = (Constants.ISBN_MODULO - (weightedSum % Constants.ISBN_MODULO))
                % Constants.ISBN_MODULO;

        // Gia tri chu so cuoi (chu so thu 13)
        lastDigit = Constants.DIGITS.indexOf(digitBuilder.charAt(Constants.ISBN_LENGTH - 1));

        // Chu so cuoi khac chu so tinh ra thi bao ca hai
        if (lastDigit != checkDigit) {
            throw new InvalidInputException(
                    String.format(Message.ERROR_ISBN_CHECKSUM, checkDigit, lastDigit));
        }

        return digitBuilder.toString();
    }

    // Kiem tu khoa tim kiem: bo dau cach 2 dau, khong duoc rong
    public static String getKeyword(String input) throws InvalidInputException {
        // Tu khoa bo dau cach 2 dau
        String keyword = input.trim();

        // Rong thi bao loi
        if (keyword.isEmpty()) {
            throw new InvalidInputException(Message.ERROR_KEYWORD_EMPTY);
        }

        return keyword;
    }

    // Kiem ten nguoi (chi chu cai khong dau + dau cach) roi chuan hoa Title Case
    private static String getPersonName(String input, String fieldName)
            throws InvalidInputException {
        // Ten da chuan hoa
        String name = toTitleCase(input);

        // Rong hoac co ky tu khac chu cai / dau cach thi bao loi kem ten o nhap
        if (!name.matches(Constants.REGEX_PERSON_NAME)) {
            throw new InvalidInputException(String.format(Message.ERROR_PERSON_NAME, fieldName));
        }

        return name;
    }

    // Doi chu thanh so nguyen; go chu thi bao loi kem ten o nhap
    private static int parseInteger(String input, String fieldName) throws InvalidInputException {
        // Thu doi chu sang so nguyen (bo dau cach 2 dau truoc)
        try {
            return Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu, so thuc hoac de trong: doi sang loi nhap, giu e lam nguyen nhan goc
            throw new InvalidInputException(String.format(Message.ERROR_NUMBER_FORMAT, fieldName),
                    e);
        }
    }

    // Bo dau cach thua, moi tu viet hoa chu dau (chuoi rong thi tra chuoi rong)
    private static String toTitleCase(String input) {
        // Chu bo dau cach 2 dau; bo noi cac tu da chuan hoa (khong dung String +=)
        String text = input.trim();
        StringBuilder resultBuilder = new StringBuilder();

        // Rong thi tra luon chuoi rong (noi goi tu bao loi)
        if (text.isEmpty()) {
            return text;
        }

        // Tach theo 1 hay nhieu dau cach, chuan hoa tung tu
        for (String word : text.split(Constants.REGEX_SPACES)) {
            // Tu thu 2 tro di thi them 1 dau cach phia truoc
            if (resultBuilder.length() > 0) {
                resultBuilder.append(Constants.SPACE);
            }

            // Chu dau viet hoa, phan con lai viet thuong
            resultBuilder.append(word.substring(0, 1).toUpperCase());
            resultBuilder.append(word.substring(1).toLowerCase());
        }

        return resultBuilder.toString();
    }
}

