khoi.controller/BookController.java:
package controller;

import constants.Constants;
import constants.Message;
import dto.BookRequestDTO;
import dto.BookResponseDTO;
import dto.LoanRequestDTO;
import exceptions.DuplicateKeyException;
import exceptions.ItemNotFoundException;
import exceptions.LibraryException;
import java.util.ArrayList;
import java.util.List;
import repository.IBookRepository;
import repository.InMemoryBookRepository;
import repository.LoanRepository;
import service.BookService;
import view.BookView;
import view.LateFeeView;
import view.ReportView;

/**
 * Dieu phoi moi yeu cau ve tai lieu (sach, tap chi, DVD): goi Repository de them/tim/sua/xoa
 * (CRUD), dua du lieu cho Service sap xep, thong ke, tinh phi, roi dua ket qua cho View in.
 * Khong import model: Controller khong biet co lop Book, Magazine hay Dvd nao ca.
 * Truong kho mang kieu INTERFACE IBookRepository: chi constructor biet ban cai dat la
 * InMemoryBookRepository — Lab 9 doi dung dong do sang FileBookRepository, Main khong doi.
 * Lab 6: day la TANG BAT loi nghiep vu. Repository nem "khong tim thay / trung", Service nem
 * "trai luat", Controller bat dung loai (hoac ca ho LibraryException) va dua cau bao cho View.
 * Khong khoi catch nao rong, khong bat Exception chung chung.
 *
 * @author CuongThai Academy
 */
public class BookController {

    // Kho tai lieu kieu INTERFACE (CRUD nam o Controller, khong o Service)
    private IBookRepository bookRepository;

    // Kho luot muon dang mo (CRUD luot muon cung nam o Controller)
    private LoanRepository loanRepository;

    // Nghiep vu sap xep, thong ke, tinh phi, luat muon
    private BookService bookService;

    // Man hinh in bang + cau thong bao
    private BookView bookView;

    // Man hinh in thong ke
    private ReportView reportView;

    // Man hinh in phi tre han
    private LateFeeView lateFeeView;

    // Tao kho, service, cac view va nap du lieu mau (sach, tap chi, DVD)
    public BookController() {
        // Dong DUY NHAT biet kho cat o dau (bo nho); Lab 9 thay bang FileBookRepository
        bookRepository = new InMemoryBookRepository();
        loanRepository = new LoanRepository();
        bookService = new BookService();
        bookView = new BookView();
        reportView = new ReportView();
        lateFeeView = new LateFeeView();

        // Nap du lieu mau; trung khoa thi in ra (khong xay ra voi du lieu mau dung)
        try {
            loadSampleItems();
        } catch (DuplicateKeyException e) {
            // Du lieu mau trung khoa thi bao loi
            showResult(e.getMessage(), new ArrayList<BookResponseDTO>());
        }
    }

    // Them 1 tai lieu, bao ket qua (thanh cong kem ma moi, hoac trung khoa)
    public void addItem(BookRequestDTO bookRequestDTO) {
        // Cau ket qua se in
        String resultMessage = "";

        // Them vao kho (kho tao dung loai + cap ma); trung khoa thi kho nem loi
        try {
            resultMessage = String.format(Message.SUCCESS_ADD,
                    bookRepository.addItem(bookRequestDTO), bookRequestDTO.getTitle(),
                    bookRepository.countItems());
        } catch (DuplicateKeyException e) {
            // Trung khoa thi lay cau bao loi cua kho
            resultMessage = e.getMessage();
        }

        // In ket qua 1 lan
        showResult(resultMessage, new ArrayList<BookResponseDTO>());
    }

    // Sua so ban cua 1 tai lieu (phieu dien ma + so ban moi), bao so cu -> so moi
    public void updateCopies(BookRequestDTO bookRequestDTO) {
        // Cau ket qua se in
        String resultMessage = "";

        // Lay ban sao TRUOC khi sua (giu so cu), roi sua trong kho
        try {
            BookResponseDTO before = bookRepository.findById(bookRequestDTO.getId());

            // Sua trong kho; ban sao "before" KHONG doi theo
            bookRepository.updateCopies(bookRequestDTO);
            resultMessage = String.format(Message.SUCCESS_UPDATE_COPIES, before.getId(),
                    before.getTitle(), before.getCopies(), bookRequestDTO.getCopies());
        } catch (ItemNotFoundException e) {
            // Khong co ma thi lay cau bao loi cua kho
            resultMessage = e.getMessage();
        }

        // In ket qua 1 lan
        showResult(resultMessage, new ArrayList<BookResponseDTO>());
    }

    // Xoa 1 tai lieu (phieu chi dien ma), bao ten tai lieu vua xoa
    public void deleteItem(BookRequestDTO bookRequestDTO) {
        // Cau ket qua se in
        String resultMessage = "";

        // Lay ban sao truoc khi xoa (de con ten ma bao), roi xoa khoi kho
        try {
            BookResponseDTO deleted = bookRepository.findById(bookRequestDTO.getId());

            // Xoa trong kho; ma nay se khong duoc cap lai
            bookRepository.deleteItem(bookRequestDTO.getId());
            resultMessage = String.format(Message.SUCCESS_DELETE, deleted.getId(),
                    deleted.getTitle(), deleted.getId());
        } catch (ItemNotFoundException e) {
            // Khong co ma thi lay cau bao loi cua kho
            resultMessage = e.getMessage();
        }

        // In ket qua 1 lan
        showResult(resultMessage, new ArrayList<BookResponseDTO>());
    }

    // Tinh phi tre han (phieu dien ma, so ngay da giu, loai nguoi muon): kho tim, Service tinh
    public void calculateLateFee(BookRequestDTO bookRequestDTO) {
        // Kho tra ban sao (da mang han muon + phi/ngay cua dung loai); Service tinh, View in
        try {
            BookResponseDTO item = bookRepository.findById(bookRequestDTO.getId());
            lateFeeView.setLateFee(bookService.calculateLateFee(item, bookRequestDTO));
            lateFeeView.display();
        } catch (ItemNotFoundException e) {
            // Khong co ma thi in cau bao loi cua kho
            showResult(e.getMessage(), new ArrayList<BookResponseDTO>());
        }
    }

    // Muon 1 tai lieu (phieu dien ma thanh vien + ma tai lieu; thanh vien da kiem truoc):
    // kho tim tai lieu, Service kiem 2 luat, roi giam 1 ban va ghi luot muon
    public void borrowItem(LoanRequestDTO loanRequestDTO) {
        // Cau ket qua se in
        String resultMessage = "";

        // Buoc nao nem loi nghiep vu thi cac buoc SAU no khong chay (khong giam ban oan)
        try {
            BookResponseDTO item = bookRepository.findById(loanRequestDTO.getItemId());
            int loanCount = loanRepository.countLoansOfMember(loanRequestDTO.getMemberId());

            // Hai luat cua Service: con han muc, con ban tren ke
            bookService.checkLoanLimit(loanRequestDTO.getMemberId(), loanCount);
            bookService.checkAvailable(item);

            // Du luat: giam 1 ban tren ke roi ghi luot muon
            bookRepository.updateCopies(toCopiesRequestDTO(item.getId(), item.getCopies() - 1));
            loanRepository.addLoan(loanRequestDTO);
            resultMessage = String.format(Message.SUCCESS_BORROW, loanRequestDTO.getMemberId(),
                    item.getId(), item.getTitle(), item.getLoanDays(), item.getCopies() - 1,
                    loanRequestDTO.getMemberId(), loanCount + 1, Constants.MAX_LOANS_PER_MEMBER);
        } catch (LibraryException e) {
            // TODO Lab 6.4 — khoi catch RONG la NUOT LOI: muon hong ma man hinh im lang.
            //   Lay cau bao cua chinh ngoai le: resultMessage = e.getMessage();
        }

        // In ket qua 1 lan
        showResult(resultMessage, new ArrayList<BookResponseDTO>());
    }

    // Tra 1 tai lieu (phieu dien ma thanh vien + ma tai lieu): xoa luot muon roi tang 1 ban
    public void returnItem(LoanRequestDTO loanRequestDTO) {
        // Cau ket qua se in
        String resultMessage = "";

        // Khong co tai lieu, hoac thanh vien khong muon no: kho nem, cac buoc sau khong chay
        try {
            BookResponseDTO item = bookRepository.findById(loanRequestDTO.getItemId());

            // Xoa luot muon truoc (sai thi dung ngay), roi moi tang so ban tren ke
            loanRepository.removeLoan(loanRequestDTO);
            bookRepository.updateCopies(toCopiesRequestDTO(item.getId(), item.getCopies() + 1));
            resultMessage = String.format(Message.SUCCESS_RETURN, loanRequestDTO.getMemberId(),
                    item.getId(), item.getTitle(), item.getCopies() + 1,
                    loanRequestDTO.getMemberId(),
                    loanRepository.countLoansOfMember(loanRequestDTO.getMemberId()),
                    Constants.MAX_LOANS_PER_MEMBER);
        } catch (LibraryException e) {
            // TODO Lab 6.4 — cung loi nuot loi nhu borrowItem: dua e.getMessage() vao resultMessage
        }

        // In ket qua 1 lan
        showResult(resultMessage, new ArrayList<BookResponseDTO>());
    }

    // Thong ke thu vien: kho dua ban sao, Service tinh, ReportView in
    public void showReport() {
        reportView.setReport(bookService.buildReport(bookRepository.findAll()));
        reportView.display();
    }

    // In moi tai lieu, sap theo ten
    public void showAllItems() {
        // Kho tra ban sao, Service sap xep + danh so
        List<BookResponseDTO> sortedList = bookService.sortByTitle(bookRepository.findAll());

        // Kho rong thi chi in cau bao rong, nguoc lai chi in bang
        if (sortedList.isEmpty()) {
            showResult(Message.EMPTY_LIST, sortedList);
        } else {
            // Co tai lieu thi in bang, khong kem cau nao
            showResult("", sortedList);
        }
    }

    // Tim tai lieu co ten chua tu khoa (phieu chi dien ten), in ket qua da sap theo ten
    public void searchItems(BookRequestDTO bookRequestDTO) {
        // Kho tim theo tu khoa, Service sap xep + danh so
        List<BookResponseDTO> foundList
                = bookService.sortByTitle(bookRepository.findByKeyword(bookRequestDTO.getTitle()));

        // Khong tim thay thi chi in cau bao, nguoc lai chi in bang
        if (foundList.isEmpty()) {
            showResult(String.format(Message.NOT_FOUND, bookRequestDTO.getTitle()), foundList);
        } else {
            // Co ket qua thi in bang
            showResult("", foundList);
        }
    }

    // Dua cau thong bao + cac dong bang cho View roi goi in dung 1 lan
    private void showResult(String message, List<BookResponseDTO> responseList) {
        bookView.setMessage(message);
        bookView.setResponseList(responseList);
        bookView.display();
    }

    // Nap du lieu mau khai trong Constants: sach, roi tap chi, roi DVD
    private void loadSampleItems() throws DuplicateKeyException {
        // Phieu dang dung cho tap chi / DVD mau
        BookRequestDTO bookRequestDTO = new BookRequestDTO();

        // Moi dong sach mau: { ten, ISBN, tac gia, nam, so ban }
        for (String[] rowArray : Constants.SAMPLE_BOOK_ARRAY) {
            bookRepository.addItem(toBookRequestDTO(rowArray));
        }

        // Moi dong tap chi mau: { ten, nam, so ban, ky so }
        for (String[] rowArray : Constants.SAMPLE_MAGAZINE_ARRAY) {
            bookRequestDTO = toCommonRequestDTO(rowArray, Constants.TYPE_MAGAZINE);
            bookRequestDTO.setIssueNumber(Integer.parseInt(rowArray[Constants.SAMPLE_EXTRA_INDEX]));
            bookRepository.addItem(bookRequestDTO);
        }

        // Moi dong DVD mau: { ten, nam, so ban, so phut }
        for (String[] rowArray : Constants.SAMPLE_DVD_ARRAY) {
            bookRequestDTO = toCommonRequestDTO(rowArray, Constants.TYPE_DVD);
            bookRequestDTO.setMinutes(Integer.parseInt(rowArray[Constants.SAMPLE_EXTRA_INDEX]));
            bookRepository.addItem(bookRequestDTO);
        }
    }

    // Doi 1 dong sach mau thanh phieu sach
    private BookRequestDTO toBookRequestDTO(String[] rowArray) {
        // Phieu moi, loai sach
        BookRequestDTO bookRequestDTO = new BookRequestDTO();
        bookRequestDTO.setItemType(Constants.TYPE_BOOK);

        // Chep tung cot cua dong mau vao phieu
        bookRequestDTO.setTitle(rowArray[Constants.SAMPLE_TITLE_INDEX]);
        bookRequestDTO.setIsbn(rowArray[Constants.SAMPLE_ISBN_INDEX]);
        bookRequestDTO.setAuthor(rowArray[Constants.SAMPLE_AUTHOR_INDEX]);
        bookRequestDTO.setYear(Integer.parseInt(rowArray[Constants.SAMPLE_YEAR_INDEX]));
        bookRequestDTO.setCopies(Integer.parseInt(rowArray[Constants.SAMPLE_COPIES_INDEX]));
        return bookRequestDTO;
    }

    // Doi phan chung cua 1 dong tap chi / DVD mau { ten, nam, so ban, ... } thanh phieu
    private BookRequestDTO toCommonRequestDTO(String[] rowArray, int itemType) {
        // Phieu moi mang loai duoc truyen vao
        BookRequestDTO bookRequestDTO = new BookRequestDTO();
